"use client";

import { useId, useRef, useState } from "react";

import { SparklesIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { AssistantMessage } from "./ai-chat/assistant-message";
import { ChatTopBar } from "./ai-chat/chat-top-bar";
import { REPLIES, THREADS } from "./ai-chat/data";
import { UserMessage } from "./ai-chat/user-message";
import { answerSize } from "./shared/answer";
import { PromptField } from "./shared/prompt-field";
import type { Rating } from "./shared/reply-actions";
import { useFollowScroll } from "./shared/use-follow-scroll";
import { useWordStream } from "./shared/use-word-stream";

interface Version {
  prompt: string;
  reply: number;
  /** Stream steps on screen when the person stopped it, or null for a full reply. */
  cut: number | null;
  rating: Rating;
}

interface Turn {
  id: number;
  versions: Version[];
  active: number;
}

interface Thread {
  id: string;
  title: string;
  turns: Turn[];
}

const STARTERS = [
  "Why did Northgate's bookings dip last week?",
  "Draft a reminder for Friday's flu clinic",
  "Which rooms are free tomorrow at 9?",
];

const opening = (): Thread[] =>
  THREADS.map((thread, index) => ({
    id: thread.id,
    title: thread.title,
    turns: [
      {
        id: index,
        versions: [
          {
            prompt: thread.opener,
            reply: thread.replyIndex,
            cut: null,
            rating: null,
          },
        ],
        active: 0,
      },
    ],
  }));

/**
 * A full chat with an assistant for clinic staff. Replies think, show the
 * tool they ran, then stream in whole-word groups that fade in once. A
 * message can be edited or a reply retried into versions; replies can be
 * rated or stopped mid-stream. Enter sends, Escape stops.
 */
export function AiChat({ className }: { className?: string }) {
  const titleId = useId();
  const [threads, setThreads] = useState<Thread[]>(opening);
  const [threadId, setThreadId] = useState(THREADS[0]!.id);
  const [modelId, setModelId] = useState("juniper-3");
  const [live, setLive] = useState<{ turn: number; version: number } | null>(
    null,
  );
  const stream = useWordStream({ delay: 900 });
  const nextReply = useRef(1);
  const nextId = useRef(THREADS.length);
  const newChats = useRef(0);

  const thread = threads.find((item) => item.id === threadId) ?? threads[0]!;
  const scroll = useFollowScroll<HTMLDivElement>(
    `${threadId}:${stream.shown}:${thread.turns.length}`,
  );

  const updateThread = (change: (turns: Turn[]) => Turn[]) =>
    setThreads((list) =>
      list.map((item) =>
        item.id === threadId ? { ...item, turns: change(item.turns) } : item,
      ),
    );

  const cutLive = () => {
    if (!live || !stream.busy) return;
    const shown = stream.status === "waiting" ? 0 : stream.shown;
    updateThread((turns) =>
      turns.map((turn) =>
        turn.id === live.turn
          ? {
              ...turn,
              versions: turn.versions.map((v, i) =>
                i === live.version ? { ...v, cut: shown } : v,
              ),
            }
          : turn,
      ),
    );
    stream.stop();
    setLive(null);
  };

  const pickReply = () => {
    const reply = nextReply.current % REPLIES.length;
    nextReply.current += 1;
    return reply;
  };

  const play = (turn: number, version: number, reply: number) => {
    setLive({ turn, version });
    scroll.pin();
    stream.start(answerSize(REPLIES[reply]!.parts), () => setLive(null));
  };

  const send = (prompt: string) => {
    cutLive();
    const id = nextId.current++;
    const reply = pickReply();
    updateThread((turns) => [
      ...turns,
      { id, versions: [{ prompt, reply, cut: null, rating: null }], active: 0 },
    ]);
    play(id, 0, reply);
  };

  const addVersion = (turnId: number, prompt: string | null) => {
    cutLive();
    const reply = pickReply();
    const turn = thread.turns.find((item) => item.id === turnId);
    if (!turn) return;
    const version = turn.versions.length;
    updateThread((turns) =>
      turns.map((item) =>
        item.id === turnId
          ? {
              ...item,
              versions: [
                ...item.versions,
                {
                  prompt: prompt ?? item.versions[item.active]!.prompt,
                  reply,
                  cut: null,
                  rating: null,
                },
              ],
              active: version,
            }
          : item,
      ),
    );
    play(turnId, version, reply);
  };

  const setTurn = (turnId: number, change: (turn: Turn) => Turn) =>
    updateThread((turns) =>
      turns.map((turn) => (turn.id === turnId ? change(turn) : turn)),
    );

  const switchThread = (id: string) => {
    cutLive();
    setThreadId(id);
  };

  const newChat = () => {
    cutLive();
    newChats.current += 1;
    const id = `new-${newChats.current}`;
    setThreads((list) => [{ id, title: "New chat", turns: [] }, ...list]);
    setThreadId(id);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      {/* Escape stops a streaming reply from anywhere in the chat. */}
      <div
        className="flex h-160 max-h-[85vh] flex-col"
        onKeyDown={(event) => {
          if (event.key === "Escape" && stream.busy && !event.defaultPrevented)
            cutLive();
        }}
      >
        <ChatTopBar
          titleId={titleId}
          threads={threads}
          threadId={threadId}
          onThread={switchThread}
          modelId={modelId}
          onModel={setModelId}
          onNewChat={newChat}
        />
        <div
          ref={scroll.ref}
          onScroll={scroll.onScroll}
          className="scroll-fade-effect-y scrollbar-none flex-1 overflow-y-auto"
        >
          <div className="mx-auto flex max-w-2xl flex-col gap-6 px-4 py-5">
            {thread.turns.length === 0 ? (
              <div className="flex flex-col items-center gap-4 py-12 text-center">
                <SparklesIcon
                  aria-hidden="true"
                  className="size-6 text-chart-2"
                />
                <p className="text-base font-semibold">
                  What can Fern look up for your clinics?
                </p>
                <div className="flex flex-wrap justify-center gap-2">
                  {STARTERS.map((starter) => (
                    <Button
                      key={starter}
                      variant="outline"
                      size="sm"

                      onClick={() => send(starter)}
                    >
                      {starter}
                    </Button>
                  ))}
                </div>
              </div>
            ) : null}
            {thread.turns.map((turn) => {
              const version = turn.versions[turn.active]!;
              const isLive =
                live?.turn === turn.id && live.version === turn.active;
              const reply = REPLIES[version.reply]!;
              const pageTo = (delta: number) =>
                setTurn(turn.id, (item) => ({
                  ...item,
                  active: item.active + delta,
                }));
              return (
                <div key={turn.id} className="flex flex-col gap-4">
                  <UserMessage
                    text={version.prompt}
                    onEdit={(text) => addVersion(turn.id, text)}
                  />
                  <AssistantMessage
                    reply={reply}
                    shown={isLive ? stream.shown : version.cut}
                    thinking={isLive && stream.status === "waiting"}
                    live={isLive}
                    stopped={version.cut !== null}
                    rating={version.rating}
                    onRate={(rating) =>
                      setTurn(turn.id, (item) => ({
                        ...item,
                        versions: item.versions.map((v, i) =>
                          i === item.active ? { ...v, rating } : v,
                        ),
                      }))
                    }
                    onRetry={() => addVersion(turn.id, null)}
                    version={{
                      index: turn.active,
                      count: turn.versions.length,
                      onPage: pageTo,
                    }}
                  />
                </div>
              );
            })}
          </div>
        </div>
        <div className="mx-auto w-full max-w-2xl px-4 pb-4">
          <p className="sr-only" aria-live="polite">
            {stream.status === "done"
              ? "Fern finished replying."
              : stream.status === "stopped"
                ? "Reply stopped."
                : ""}
          </p>
          <PromptField
            label="Message Fern"
            placeholder="Ask about bookings, rooms or patients"
            busy={stream.busy}
            onSend={send}
            onStop={cutLive}
          />
        </div>
      </div>
    </BlockFrame>
  );
}

