"use client";

import { SparklesIcon } from "@/components/blocks/parts/icons";

import { answerSize, answerText } from "../shared/answer";
import { type Rating, ReplyActions } from "../shared/reply-actions";
import { StreamAnswer } from "../shared/stream-answer";
import { ThoughtRow } from "../shared/thought-row";
import type { ChatReply } from "./data";
import { ToolChip } from "./tool-chip";

/** Props for one reply from the assistant. */
export interface AssistantMessageProps {
  reply: ChatReply;
  /** Stream steps on screen. Null for a finished reply. */
  shown: number | null;
  /** True before the first words arrive. */
  thinking: boolean;
  live: boolean;
  stopped: boolean;
  rating: Rating;
  onRate: (rating: Rating) => void;
  onRetry?: () => void;
  version: { index: number; count: number; onPage: (delta: number) => void };
}

/**
 * One reply: the folded reasoning, the tool it ran with its sources, then the
 * answer. While live the answer grows a few words per tick; actions appear
 * once it ends or is stopped.
 */
export function AssistantMessage({
  reply,
  shown,
  thinking,
  live,
  stopped,
  rating,
  onRate,
  onRetry,
  version,
}: AssistantMessageProps) {
  const total = answerSize(reply.parts);
  const visible = shown ?? total;
  const finished = !live || stopped;
  return (
    <article aria-label="Reply from Fern" className="flex gap-3">
      <span
        aria-hidden="true"
        className="mt-0.5 flex size-7 shrink-0 items-center justify-center rounded-full bg-chart-2/20 text-chart-2"
      >
        <SparklesIcon className="size-4" />
      </span>
      <div className="flex min-w-0 flex-1 flex-col gap-3">
        <ThoughtRow
          thinking={thinking}
          seconds={reply.seconds}
          thought={reply.thought}
        />
        {thinking ? null : (
          <>
            <ToolChip label={reply.tool.label} sources={reply.tool.sources} />
            <StreamAnswer parts={reply.parts} shown={visible} live={live} />
          </>
        )}
        {stopped ? (
          <p className="text-xs text-muted-foreground">
            You stopped this reply.
          </p>
        ) : null}
        {finished && !thinking ? (
          <ReplyActions
            className="-ml-1.5"
            text={answerText(reply.parts)}
            rating={rating}
            onRate={onRate}
            onRetry={onRetry}
            version={version}
          />
        ) : null}
      </div>
    </article>
  );
}

/** One block of a formatted reply. Inline `code` and citations like [2] live inside the text. */
export type AnswerPart =
  | { kind: "p"; text: string }
  | { kind: "h"; text: string }
  | { kind: "steps"; items: string[] }
  | { kind: "bullets"; items: string[] }
  | { kind: "code"; label: string; text: string }
  | { kind: "table"; head: string[]; rows: string[][] };

/** Splits a run of text into the words a stream reveals one group at a time. */
export const words = (text: string) => text.split(/\s+/).filter(Boolean);

/** How many stream steps one part takes: a word of text, a line of code or a row of a table. */
export function partSize(part: AnswerPart): number {
  switch (part.kind) {
    case "p":
    case "h":
      return words(part.text).length;
    case "steps":
    case "bullets":
      return part.items.reduce((sum, item) => sum + words(item).length, 0);
    case "code":
      return part.text.split("\n").length;
    case "table":
      return part.rows.length + 1;
  }
}

/** The number of stream steps a whole reply takes. */
export const answerSize = (parts: AnswerPart[]) =>
  parts.reduce((sum, part) => sum + partSize(part), 0);

/** The reply as plain text, for Copy. */
export function answerText(parts: AnswerPart[]): string {
  return parts
    .map((part) => {
      switch (part.kind) {
        case "p":
        case "h":
          return part.text;
        case "steps":
          return part.items
            .map((item, index) => `${index + 1}. ${item}`)
            .join("\n");
        case "bullets":
          return part.items.map((item) => `- ${item}`).join("\n");
        case "code":
          return part.text;
        case "table":
          return [part.head, ...part.rows]
            .map((row) => row.join(" | "))
            .join("\n");
      }
    })
    .join("\n\n")
    .replace(/`/g, "");
}

"use client";

import { type ReactNode, useEffect, useRef, useState } from "react";

import {
  CheckIcon,
  ChevronRightIcon,
  RefreshIcon,
} from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import {
  ChevronLeftIcon,
  CopyIcon,
  ThumbDownIcon,
  ThumbUpIcon,
} from "../icons";

/** A person's rating of one reply. */
export type Rating = "up" | "down" | null;

/** Props for the row of actions under a reply. */
export interface ReplyActionsProps {
  /** The reply as plain text, for Copy. */
  text: string;
  rating: Rating;
  onRate: (rating: Rating) => void;
  onRetry?: () => void;
  /** Which version shows, out of how many, when a reply was retried or its prompt edited. */
  version?: { index: number; count: number; onPage: (delta: number) => void };
  /** Extra actions, such as a regenerate menu. */
  children?: ReactNode;
  className?: string;
}

/**
 * Copy, retry, rate and page through versions of one reply. Copy confirms
 * for two seconds, and its timer is cleared if the reply goes away first.
 */
export function ReplyActions({
  text,
  rating,
  onRate,
  onRetry,
  version,
  children,
  className,
}: ReplyActionsProps) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );
  const copy = () => {
    void navigator.clipboard?.writeText(text).catch(() => undefined);
    setCopied(true);
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => setCopied(false), 2000);
  };
  const icon = "size-7";
  return (
    <div className={cn("flex flex-wrap items-center gap-0.5", className)}>
      {version && version.count > 1 ? (
        <span className="mr-1 flex items-center text-xs text-muted-foreground tabular-nums">
          <Button
            variant="ghost"
            size="icon"
            className={icon}
            aria-label="Earlier version"
            disabled={version.index === 0}
            onClick={() => version.onPage(-1)}
          >
            <ChevronLeftIcon aria-hidden="true" className="size-3.5" />
          </Button>
          <span aria-live="polite">
            {version.index + 1} of {version.count}
          </span>
          <Button
            variant="ghost"
            size="icon"
            className={icon}
            aria-label="Later version"
            disabled={version.index === version.count - 1}
            onClick={() => version.onPage(1)}
          >
            <ChevronRightIcon aria-hidden="true" className="size-3.5" />
          </Button>
        </span>
      ) : null}
      <Button
        variant="ghost"
        size="icon"
        className={icon}
        aria-label={copied ? "Copied" : "Copy reply"}
        onClick={copy}
      >
        {copied ? (
          <CheckIcon aria-hidden="true" className="size-3.5" />
        ) : (
          <CopyIcon aria-hidden="true" className="size-3.5" />
        )}
      </Button>
      {onRetry ? (
        <Button
          variant="ghost"
          size="icon"
          className={icon}
          aria-label="Retry"
          onClick={onRetry}
        >
          <RefreshIcon aria-hidden="true" className="size-3.5" />
        </Button>
      ) : null}
      <Button
        variant="ghost"
        size="icon"
        className={icon}
        aria-label="Good reply"
        aria-pressed={rating === "up"}
        onClick={() => onRate(rating === "up" ? null : "up")}
      >
        <ThumbUpIcon
          aria-hidden="true"
          className="size-3.5"
          fill={rating === "up" ? "currentColor" : "none"}
        />
      </Button>
      <Button
        variant="ghost"
        size="icon"
        className={icon}
        aria-label="Poor reply"
        aria-pressed={rating === "down"}
        onClick={() => onRate(rating === "down" ? null : "down")}
      >
        <ThumbDownIcon
          aria-hidden="true"
          className="size-3.5"
          fill={rating === "down" ? "currentColor" : "none"}
        />
      </Button>
      {children}
    </div>
  );
}

