/** Props for a formatted reply that may still be arriving. */
export interface StreamAnswerProps {
  parts: AnswerPart[];
  /** How many stream steps are on screen. Pass the full size for a finished reply. */
  shown: number;
  live?: boolean;
  renderCite?: CiteRenderer;
  /** Tints every paragraph and list item that cites this source. */
  litCite?: number | null;
  className?: string;
}

const cites = (text: string, index: number | null | undefined) =>
  index != null && text.includes(`[${index}]`);

const LIT = "rounded-md bg-chart-2/15 box-decoration-clone";

/**
 * A reply laid out as prose, headings, numbered steps, a table and code.
 * Each part takes its share of the stream in order, so the reply grows from
 * the top and nothing above the newest words moves.
 */
export function StreamAnswer({
  parts,
  shown,
  live = false,
  renderCite,
  litCite,
  className,
}: StreamAnswerProps) {
  let start = 0;
  return (
    <div
      className={cn("flex flex-col gap-3 text-sm leading-relaxed", className)}
    >
      {parts.map((part, index) => {
        const at = start;
        start += partSize(part);
        if (shown <= at) return null;
        const text = (value: string, offset: number) => (
          <StreamText
            text={value}
            start={offset}
            shown={shown}
            live={live}
            renderCite={renderCite}
          />
        );
        switch (part.kind) {
          case "p":
            return (
              <p key={index} className={cn(cites(part.text, litCite) && LIT)}>
                {text(part.text, at)}
              </p>
            );
          case "h":
            return (
              <h4 key={index} className="pt-1 text-sm font-semibold">
                {text(part.text, at)}
              </h4>
            );
          case "steps":
          case "bullets": {
            let offset = at;
            const List = part.kind === "steps" ? "ol" : "ul";
            return (
              <List
                key={index}
                className={cn(
                  "flex flex-col gap-1.5 pl-5",
                  part.kind === "steps" ? "list-decimal" : "list-disc",
                )}
              >
                {part.items.map((item, itemIndex) => {
                  const itemAt = offset;
                  offset += words(item).length;
                  return shown > itemAt ? (
                    <li
                      key={itemIndex}
                      className={cn(
                        "pl-1 marker:text-muted-foreground",
                        cites(item, litCite) && LIT,
                      )}
                    >
                      {text(item, itemAt)}
                    </li>
                  ) : null;
                })}
              </List>
            );
          }
          case "code": {
            const lines = part.text.split("\n").slice(0, shown - at);
            return (
              <figure
                key={index}
                className="overflow-hidden rounded-lg border border-border"
              >
                <figcaption className="flex items-center justify-between gap-2 border-b border-border px-3 py-1 text-xs text-muted-foreground">
                  {part.label}
                  <CopyButton value={part.text} label="Copy" />
                </figcaption>
                <pre className="overflow-x-auto p-3 font-mono text-xs leading-relaxed">
                  <code>{lines.join("\n")}</code>
                </pre>
              </figure>
            );
          }
          case "table": {
            const rows = part.rows.slice(0, shown - at - 1);
            return (
              <div
                key={index}
                className="overflow-hidden rounded-lg border border-border tabular-nums"
              >
                <Table>
                  <TableHeader>
                    <TableRow>
                      {part.head.map((cell) => (
                        <TableHead key={cell} scope="col">
                          <span className="text-xs text-muted-foreground">
                            {cell}
                          </span>
                        </TableHead>
                      ))}
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {rows.map((row, rowIndex) => (
                      <TableRow key={rowIndex}>
                        {row.map((cell, cellIndex) => (
                          <TableCell key={cellIndex}>
                            <span
                              className={cn(
                                live &&
                                  "motion-safe:animate-in motion-safe:fade-in",
                              )}
                            >
                              {cell}
                            </span>
                          </TableCell>
                        ))}
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            );
          }
        }
      })}
    </div>
  );
}

import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

import { words } from "./answer";
import { STREAM_CHUNK } from "./use-word-stream";

/** Draws one citation number. Blocks pass their own to make it a button. */
export type CiteRenderer = (index: number) => ReactNode;

/** Props for a run of text that arrives a few words at a time. */
export interface StreamTextProps {
  text: string;
  /** The stream step of this run's first word. */
  start: number;
  /** How many stream steps are on screen across the whole reply. */
  shown: number;
  /** Fades each new group of words in once. Off for a reply that is already complete. */
  live?: boolean;
  renderCite?: CiteRenderer;
}

/** The plain citation mark: a small raised number. */
export function CiteMark({ index }: { index: number }) {
  return (
    <sup className="mx-0.5 inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-muted px-1 text-xs font-medium text-muted-foreground tabular-nums">
      {index}
    </sup>
  );
}

const defaultCite: CiteRenderer = (index) => <CiteMark index={index} />;

/** One word, with inline `code` and a [2] citation drawn as marks. */
function renderWord(word: string, renderCite: CiteRenderer): ReactNode {
  const code = /^`([^`]+)`(.*)$/.exec(word);
  if (code) {
    return (
      <span className="whitespace-nowrap">
        <code className="rounded bg-muted px-1 py-0.5 font-mono text-xs">
          {code[1]}
        </code>
        {code[2]}
      </span>
    );
  }
  const cite = /^\[(\d+)\](.*)$/.exec(word);
  if (cite) {
    return (
      <span className="whitespace-nowrap">
        {renderCite(Number(cite[1]))}
        {cite[2]}
      </span>
    );
  }
  return word;
}

/**
 * Text whose words appear in fixed groups. Each group mounts once and fades
 * in once, so words already on screen never re-render or move.
 */
export function StreamText({
  text,
  start,
  shown,
  live = false,
  renderCite = defaultCite,
}: StreamTextProps) {
  const list = words(text);
  const visible = Math.max(0, Math.min(list.length, shown - start));
  const groups: { key: number; items: string[] }[] = [];
  for (let index = 0; index < visible; index++) {
    const key = Math.floor((start + index) / STREAM_CHUNK);
    const last = groups.at(-1);
    if (last && last.key === key) last.items.push(list[index]!);
    else groups.push({ key, items: [list[index]!] });
  }
  return (
    <>
      {groups.map((group) => (
        <span
          key={group.key}
          className={cn(
            live &&
              "motion-safe:animate-in motion-safe:fade-in motion-safe:duration-500",
          )}
        >
          {group.items.map((word, index) => (
            <span key={index}>{renderWord(word, renderCite)} </span>
          ))}
        </span>
      ))}
    </>
  );
}

