        </DropdownMenuContent>
      </DropdownMenu>
      <Button
        variant="ghost"
        size="icon"
        className="size-8"
        aria-label="New chat"
        onClick={onNewChat}
      >
        <PlusIcon aria-hidden="true" className="size-4" />
      </Button>
    </header>
  );
}

