"use client";

import { type KeyboardEvent, useState } from "react";

import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

import { PencilIcon } from "../icons";

/** Props for the person's message bubble. */
export interface UserMessageProps {
  text: string;
  /** Saves an edited message as a new version and asks again. Omit while a reply streams. */
  onEdit?: (text: string) => void;
}

/**
 * The person's message as a bubble on the right. Edit opens it in place:
 * Enter sends the new version, Shift and Enter adds a line, Escape cancels.
 */
export function UserMessage({ text, onEdit }: UserMessageProps) {
  const [draft, setDraft] = useState<string | null>(null);

  const save = () => {
    const value = draft?.trim();
    setDraft(null);
    if (value && value !== text) onEdit?.(value);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      save();
    } else if (event.key === "Escape") {
      event.preventDefault();
      setDraft(null);
    }
  };

  if (draft !== null) {
    return (
      <div className="ml-auto flex w-full max-w-md flex-col gap-2">
        <Textarea
          aria-label="Edit your message"
          autoFocus
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={onKeyDown}
          className="resize-none"
        />
        <div className="flex justify-end gap-2">
          <Button variant="ghost" size="sm" onClick={() => setDraft(null)}>
            Cancel
          </Button>
          <Button size="sm" onClick={save}>
            Send
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="group ml-auto flex max-w-md items-start gap-1">
      {onEdit ? (
        <span className="shrink-0 opacity-0 group-hover:opacity-100 focus-within:opacity-100 [@media(hover:none)]:opacity-100">
          <Button variant="ghost" size="icon" className="size-7" aria-label="Edit message" onClick={() => setDraft(text)}>
            <PencilIcon aria-hidden="true" className="size-3.5" />
          </Button>
        </span>
      ) : null}
      <p className="rounded-2xl rounded-br-md bg-primary px-3.5 py-2 text-sm whitespace-pre-wrap text-primary-foreground">
        {text}
      </p>
    </div>
  );
}

"use client";

import { type KeyboardEvent, type ReactNode, useState } from "react";

import { ArrowUpIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

import { StopIcon } from "../icons";

/** Props for the message field at the foot of a chat. */
export interface PromptFieldProps {
  label: string;
  placeholder: string;
  /** True while a reply streams: the send button turns into stop. */
  busy: boolean;
  onSend: (text: string) => void;
  onStop: () => void;
  /** Extra controls on the left of the action row, such as attach. */
  tools?: ReactNode;
  /** Text that sits above the field, such as a quoted passage. */
  context?: ReactNode;
  className?: string;
}

/**
 * A message field that grows with its text. Enter sends, Shift and Enter adds
 * a line, and Escape stops a streaming reply.
 */
export function PromptField({
  label,
  placeholder,
  busy,
  onSend,
  onStop,
  tools,
  context,
  className,
}: PromptFieldProps) {
  const [text, setText] = useState("");
  const send = () => {
    const value = text.trim();
    if (!value || busy) return;
    onSend(value);
    setText("");
  };
  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      send();
    } else if (event.key === "Escape" && busy) {
      event.preventDefault();
      onStop();
    }
  };
  return (
    <div
      className={cn("flex flex-col gap-2", className)}
    >
      {context}
      <Textarea
        aria-label={label}
        placeholder={placeholder}
        value={text}
        rows={1}
        onChange={(event) => setText(event.target.value)}
        onKeyDown={onKeyDown}
        className="max-h-40 min-h-10 resize-none"
      />
      <div className="flex items-center gap-1">
        {tools}
        <span className="flex-1" />
        {busy ? (
          <Button
            size="icon"
            variant="secondary"
            className="size-8"
            aria-label="Stop the reply"
            onClick={onStop}
          >
            <StopIcon aria-hidden="true" className="size-3.5" />
          </Button>
        ) : (
          <Button
            size="icon"
            className="size-8"
            aria-label="Send"
            disabled={!text.trim()}
            onClick={send}
          >
            <ArrowUpIcon aria-hidden="true" className="size-4" />
          </Button>
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";

/**
 * Keeps a scroll box pinned to its end while new content arrives, until the
 * reader scrolls up. Scrolling back to the end pins it again. Pass any value
 * that changes as content grows as `watch`.
 */
export function useFollowScroll<T extends HTMLElement>(watch: string | number) {
  const ref = useRef<T>(null);
  const pinned = useRef(true);

  const onScroll = useCallback(() => {
    const box = ref.current;
    if (!box) return;
    pinned.current = box.scrollHeight - box.scrollTop - box.clientHeight < 24;
  }, []);

  useEffect(() => {
    const box = ref.current;
    if (box && pinned.current) box.scrollTop = box.scrollHeight;
  }, [watch]);

  /** Pins the box again, such as when the person sends a new message. */
  const pin = useCallback(() => {
    pinned.current = true;
  }, []);

  return { ref, onScroll, pin };
}
